            //
            //     [
            //         {
            //             "trading": "Enabled",
            //             "base_decimals": 8,
            //             "url_symbol": "btcusd",
            //             "name": "BTC/USD",
            //             "instant_and_market_orders": "Enabled",
            //             "minimum_order": "20.0 USD",
            //             "counter_decimals": 2,
